    "content": "import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1 + n]))

    # dp[i] = longest increasing subsequence ending at position i
    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if a[j] < a[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    # b[i] = longest decreasing subsequence starting at position i
    b = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if a[j] < a[i]:
                b[i] = max(b[i], b[j] + 1)

    print(sum(b))

if __name__ == "__main__":
    solve()
